using Microsoft.EntityFrameworkCore; namespace KeHoachDaNgoai.Models; public class QLDaNgoaiContext:DbContext { public QLDaNgoaiContext(DbContextOptions<QLDaNgoaiContext> options):base(options){} public DbSet<ChuyenDi> ChuyenDi=>Set<ChuyenDi>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<ChuyenDi>().ToTable("ChuyenDi").HasKey(x=>x.MaChuyen); b.Entity<ChuyenDi>().Property(x=>x.TenChuyen).HasMaxLength(100).IsRequired(); b.Entity<ChuyenDi>().Property(x=>x.DiaDiem).HasMaxLength(100).IsRequired(); b.Entity<ChuyenDi>().Property(x=>x.NganSach).HasColumnType("decimal(18,0)"); b.Entity<ChuyenDi>().Property(x=>x.GhiChu).HasMaxLength(200);}}